// Animated counter
const Counter: React.FC<{ target: number; labelKey: string; suffix?: string }> = ({ target, labelKey, suffix = '' }) => {
  const { t } = useTranslation();
  const [count, setCount] = useState(0);
  useEffect(() => {
    let start = 0;
    const duration = 2000;
    const stepTime = 20;
    const steps = duration / stepTime;
    const increment = target / steps;
    const timer = setInterval(() => {
      start += increment;
      if (start >= target) {
        setCount(target);
        clearInterval(timer);
      } else {
        setCount(Math.floor(start));
      }
    }, stepTime);
    return () => clearInterval(timer);
  }, [target]);
  return (
    <div className="text-center p-4 bg-white rounded-xl shadow-md">
      
      <div className="text-3xl md:text-4xl font-bold text-[#B22234]">{count}{suffix}</div>
      <div className="text-sm text-gray-600 mt-1">{t(labelKey)}</div>
    </div>
  );
};

// Did You Know? rotator
const factsKeys = ['fact1', 'fact2', 'fact3', 'fact4', 'fact5'];

const FactRotator: React.FC = () => {
  const { t } = useTranslation();
  const [index, setIndex] = useState(0);
  useEffect(() => {
    const interval = setInterval(() => {
      setIndex((prev) => (prev + 1) % factsKeys.length);
    }, 5000);
    return () => clearInterval(interval);
  }, []);
  return (
    <div className="bg-gradient-to-r from-[#0B3B60] to-[#082A45] rounded-xl p-6 text-white shadow-lg">
      <div className="flex items-center gap-3 mb-3">
        <FaLightbulb className="text-[#FFD700] text-2xl" />
        <h3 className="text-xl font-bold">{t('didYouKnow')}</h3>
      </div>
      <p className="text-gray-100 text-sm md:text-base transition-opacity duration-500">
        {t(factsKeys[index])}
      </p>
    </div>
  );
};

